<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Your photos are ready</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><style>body{background:#0d0c11;color:#fff}.final-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:8px}.final-photo{position:relative;overflow:hidden;border-radius:8px}.final-photo img{width:100%;aspect-ratio:4/3;object-fit:cover;cursor:zoom-in}.final-photo label{position:absolute;top:10px;left:10px;padding:7px 10px;border-radius:20px;background:#fff;color:#111}.final-photo a{position:absolute;right:10px;bottom:10px}.delivery-bar{position:sticky;bottom:10px;z-index:20;padding:12px;background:#fff;color:#111;border-radius:14px}.preview-nav{position:absolute;top:50%;transform:translateY(-50%);z-index:2;border:0;border-radius:50%;width:48px;height:48px}.preview-prev{left:12px}.preview-next{right:12px}@media(max-width:600px){.final-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}.final-photo label{font-size:.7rem;padding:5px 7px}.final-photo a{font-size:0;width:38px;height:38px;border-radius:50%}.final-photo a:after{content:'↓';font-size:1rem}.delivery-bar{align-items:stretch!important;flex-direction:column;gap:8px}.delivery-actions{display:grid!important;grid-template-columns:1fr 1fr}.delivery-actions #download-selected{grid-column:1/-1}.preview-nav{width:40px;height:40px}}</style></head><body>
<header class="text-center py-5"><p class="text-white-50">{{ $gallery->business->name }}</p><h1>Your Photos Are Ready!</h1><h2 class="h4">{{ $gallery->name }}</h2><p>{{ $photos->total() }} final edited photos</p></header>
<main class="container pb-5"><form method="POST" action="{{ route('delivery.zip',$token) }}">@csrf<div class="final-grid">@foreach($photos as $photo)<article class="final-photo" data-name="{{ $photo->filename }}"><img loading="lazy" src="{{ route('delivery.image',[$token,$photo]) }}" alt="{{ $photo->filename }}" onclick="openPreview(this)"><label><input class="choice" type="checkbox" name="photos[]" value="{{ $photo->id }}"> Select</label><a class="btn btn-light btn-sm" href="{{ route('delivery.download',[$token,$photo]) }}" aria-label="Download {{ $photo->filename }}">Download</a></article>@endforeach</div>{{ $photos->links() }}<div class="delivery-bar d-flex justify-content-between align-items-center mt-4"><b><span id="selected">0</span> photos selected</b><div class="delivery-actions d-flex gap-2"><button type="button" class="btn btn-light" onclick="setAll(true)">Select page</button><button type="button" class="btn btn-light" onclick="setAll(false)">Clear</button><button class="btn btn-dark" id="download-selected" disabled>Download selected</button></div></div></form><form method="POST" action="{{ route('delivery.zip',$token) }}" class="text-center mt-3">@csrf<input type="hidden" name="all" value="1"><button class="btn btn-outline-light btn-lg">Download all photos</button></form></main>
<div class="modal fade" id="preview" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-xl modal-dialog-centered"><div class="modal-content bg-dark"><div class="modal-body text-center p-0"><img id="preview-image" class="img-fluid" style="max-height:88vh" alt=""><div id="preview-name" class="position-absolute bottom-0 start-50 translate-middle-x bg-dark bg-opacity-75 px-3 py-2 rounded-top"></div><button class="preview-nav preview-prev" type="button" onclick="movePreview(-1)" aria-label="Previous photo"><i class="bi bi-chevron-left"></i></button><button class="preview-nav preview-next" type="button" onclick="movePreview(1)" aria-label="Next photo"><i class="bi bi-chevron-right"></i></button><button class="btn-close btn-close-white position-absolute top-0 end-0 m-3" data-bs-dismiss="modal" aria-label="Close"></button></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>const boxes=[...document.querySelectorAll('.choice')],cards=[...document.querySelectorAll('.final-photo')],count=document.getElementById('selected'),button=document.getElementById('download-selected');let previewIndex=0;function update(){const n=boxes.filter(x=>x.checked).length;count.textContent=n;button.disabled=!n}boxes.forEach(x=>x.onchange=update);function setAll(value){boxes.forEach(x=>x.checked=value);update()}function displayPreview(){const card=cards[previewIndex],img=card.querySelector('img'),target=document.getElementById('preview-image');target.src=img.src;target.alt=img.alt;document.getElementById('preview-name').textContent=`${previewIndex+1} / ${cards.length} · ${card.dataset.name}`}function openPreview(img){previewIndex=cards.indexOf(img.closest('.final-photo'));displayPreview();bootstrap.Modal.getOrCreateInstance(document.getElementById('preview')).show()}function movePreview(step){previewIndex=(previewIndex+step+cards.length)%cards.length;displayPreview()}document.addEventListener('keydown',event=>{if(!document.getElementById('preview').classList.contains('show'))return;if(event.key==='ArrowLeft')movePreview(-1);if(event.key==='ArrowRight')movePreview(1)});</script></body></html>
